import re
from dataclasses import dataclass, field
from typing import Optional

HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)
# Maintainer comments: one line or several, inline or on their own. The
# horizontal whitespace before a comment goes with it, so no trailing
# whitespace is left behind.
COMMENT = re.compile(r"[ \t]*<!--.*?-->", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def parse_changelog(text):
    # Strip comments first so a commented-out "## " line is not taken as a heading.
    text = COMMENT.sub("", text)
    releases = []
    current = None
    for line in text.splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                # Some other level-2 heading: its body belongs to no release.
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _clean_body(lines):
    cleaned = []
    for line in lines:
        if line.strip() == "":
            line = ""
        if line == "" and (not cleaned or cleaned[-1] == ""):
            continue
        cleaned.append(line)
    while cleaned and cleaned[-1] == "":
        cleaned.pop()
    return "\n".join(cleaned)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            heading = f"# {release.version} ({release.date})" if release.date else "# Unreleased"
            body = _clean_body(release.body)
            return f"{heading}\n\n{body}\n"
    raise LookupError(version)
